# Terraform Module: S3 + RDS + IAM

## Project Structure

```
terraform/
├── modules/
│   └── app-infrastructure/
│       ├── main.tf
│       ├── variables.tf
│       ├── outputs.tf
│       └── versions.tf
├── environments/
│   ├── dev/
│   │   ├── main.tf
│   │   ├── backend.tf
│   │   ├── terraform.tfvars
│   │   └── secrets.sops.yaml (encrypted, not in git as plaintext)
│   └── prod/
│       ├── main.tf
│       ├── backend.tf
│       ├── terraform.tfvars
│       └── secrets.sops.yaml (encrypted, not in git as plaintext)
└── .gitignore
```

---

## Module: `modules/app-infrastructure/`

### `versions.tf`

```terraform
terraform {
  required_version = ">= 1.5"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}
```

### `variables.tf`

```terraform
# ---------------------------------------------------------------------------
# General
# ---------------------------------------------------------------------------

variable "environment" {
  description = "Environment name (dev or prod)"
  type        = string

  validation {
    condition     = contains(["dev", "prod"], var.environment)
    error_message = "Environment must be 'dev' or 'prod'."
  }
}

variable "project" {
  description = "Project name used for resource naming and tagging"
  type        = string
}

variable "region" {
  description = "AWS region"
  type        = string
}

variable "tags" {
  description = "Additional tags applied to all resources"
  type        = map(string)
  default     = {}
}

# ---------------------------------------------------------------------------
# S3
# ---------------------------------------------------------------------------

variable "bucket_name" {
  description = "Name of the S3 bucket (will be prefixed with project-environment)"
  type        = string
}

variable "enable_replication" {
  description = "Enable cross-region replication (prod)"
  type        = bool
  default     = false
}

variable "replication_region" {
  description = "Destination region for cross-region replication"
  type        = string
  default     = "us-west-2"
}

# ---------------------------------------------------------------------------
# RDS
# ---------------------------------------------------------------------------

variable "db_instance_class" {
  description = "RDS instance class"
  type        = string
}

variable "db_name" {
  description = "Initial database name"
  type        = string
  default     = "appdb"
}

variable "db_username" {
  description = "Master username for RDS"
  type        = string
  default     = "dbadmin"
  sensitive   = true
}

variable "db_password" {
  description = "Master password for RDS (pass via SOPS or TF_VAR)"
  type        = string
  sensitive   = true
}

variable "db_multi_az" {
  description = "Enable Multi-AZ deployment"
  type        = bool
  default     = false
}

variable "db_allocated_storage" {
  description = "Allocated storage in GB"
  type        = number
  default     = 20
}

variable "db_backup_retention_period" {
  description = "Backup retention in days (minimum 7)"
  type        = number
  default     = 7

  validation {
    condition     = var.db_backup_retention_period >= 7
    error_message = "Backup retention must be at least 7 days."
  }
}

variable "db_subnet_ids" {
  description = "Subnet IDs for the DB subnet group"
  type        = list(string)
}

variable "db_security_group_ids" {
  description = "Security group IDs to attach to RDS"
  type        = list(string)
}

# ---------------------------------------------------------------------------
# IAM
# ---------------------------------------------------------------------------

variable "oidc_provider_arn" {
  description = "ARN of the EKS OIDC provider (for IRSA). Empty string = use access keys instead."
  type        = string
  default     = ""
}

variable "oidc_provider_url" {
  description = "URL of the EKS OIDC provider (without https://)"
  type        = string
  default     = ""
}

variable "service_account_namespace" {
  description = "Kubernetes namespace of the service account"
  type        = string
  default     = "default"
}

variable "service_account_name" {
  description = "Kubernetes service account name"
  type        = string
  default     = "app-sa"
}
```

### `main.tf`

```terraform
locals {
  name_prefix = "${var.project}-${var.environment}"
  common_tags = merge(
    {
      Project     = var.project
      Environment = var.environment
      ManagedBy   = "terraform"
    },
    var.tags
  )
}

# ---------------------------------------------------------------------------
# S3 Bucket
# ---------------------------------------------------------------------------

resource "aws_s3_bucket" "app" {
  bucket = "${local.name_prefix}-${var.bucket_name}"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-${var.bucket_name}"
  })
}

resource "aws_s3_bucket_versioning" "app" {
  bucket = aws_s3_bucket.app.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "app" {
  bucket = aws_s3_bucket.app.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "app" {
  bucket = aws_s3_bucket.app.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# --- Cross-region replication (prod only) -----------------------------------

resource "aws_s3_bucket" "replica" {
  count    = var.enable_replication ? 1 : 0
  provider = aws.replica
  bucket   = "${local.name_prefix}-${var.bucket_name}-replica"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-${var.bucket_name}-replica"
  })
}

resource "aws_s3_bucket_versioning" "replica" {
  count    = var.enable_replication ? 1 : 0
  provider = aws.replica
  bucket   = aws_s3_bucket.replica[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica" {
  count    = var.enable_replication ? 1 : 0
  provider = aws.replica
  bucket   = aws_s3_bucket.replica[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "replica" {
  count    = var.enable_replication ? 1 : 0
  provider = aws.replica
  bucket   = aws_s3_bucket.replica[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_iam_role" "replication" {
  count = var.enable_replication ? 1 : 0
  name  = "${local.name_prefix}-s3-replication"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "s3.amazonaws.com"
      }
    }]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy" "replication" {
  count = var.enable_replication ? 1 : 0
  name  = "${local.name_prefix}-s3-replication"
  role  = aws_iam_role.replication[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket",
        ]
        Effect   = "Allow"
        Resource = [aws_s3_bucket.app.arn]
      },
      {
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging",
        ]
        Effect   = "Allow"
        Resource = ["${aws_s3_bucket.app.arn}/*"]
      },
      {
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags",
        ]
        Effect   = "Allow"
        Resource = ["${aws_s3_bucket.replica[0].arn}/*"]
      },
    ]
  })
}

resource "aws_s3_bucket_replication_configuration" "app" {
  count  = var.enable_replication ? 1 : 0
  bucket = aws_s3_bucket.app.id
  role   = aws_iam_role.replication[0].arn

  rule {
    id     = "replicate-all"
    status = "Enabled"

    destination {
      bucket        = aws_s3_bucket.replica[0].arn
      storage_class = "STANDARD"
    }
  }

  depends_on = [aws_s3_bucket_versioning.app]
}

# ---------------------------------------------------------------------------
# RDS PostgreSQL
# ---------------------------------------------------------------------------

resource "aws_db_subnet_group" "app" {
  name       = "${local.name_prefix}-db"
  subnet_ids = var.db_subnet_ids

  tags = local.common_tags
}

resource "aws_db_instance" "app" {
  identifier = "${local.name_prefix}-postgres"

  # Engine
  engine               = "postgres"
  engine_version       = "16.3"
  instance_class       = var.db_instance_class
  allocated_storage    = var.db_allocated_storage
  storage_type         = "gp3"
  storage_encrypted    = true

  # Database
  db_name  = var.db_name
  username = var.db_username
  password = var.db_password

  # Networking
  db_subnet_group_name   = aws_db_subnet_group.app.name
  vpc_security_group_ids = var.db_security_group_ids
  publicly_accessible    = false
  multi_az               = var.db_multi_az

  # Backup & maintenance
  backup_retention_period   = var.db_backup_retention_period
  backup_window             = "03:00-04:00"
  maintenance_window        = "sun:05:00-sun:06:00"
  copy_tags_to_snapshot     = true
  delete_automated_backups  = false

  # Protection
  deletion_protection = true
  skip_final_snapshot = false
  final_snapshot_identifier = "${local.name_prefix}-postgres-final"

  # Monitoring
  performance_insights_enabled = var.environment == "prod"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-postgres"
  })
}

# ---------------------------------------------------------------------------
# IAM — Service Account Role
# ---------------------------------------------------------------------------

# --- Policy: least-privilege S3 access for the application -----------------

data "aws_iam_policy_document" "app_s3" {
  statement {
    sid    = "AllowListBucket"
    effect = "Allow"
    actions = [
      "s3:ListBucket",
      "s3:GetBucketLocation",
    ]
    resources = [aws_s3_bucket.app.arn]
  }

  statement {
    sid    = "AllowObjectOperations"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:DeleteObject",
    ]
    resources = ["${aws_s3_bucket.app.arn}/*"]
  }

  # Prod: no wildcard actions — explicitly deny anything not listed above
  dynamic "statement" {
    for_each = var.environment == "prod" ? [1] : []
    content {
      sid    = "DenyNonS3Actions"
      effect = "Deny"
      actions = [
        "s3:PutBucketPolicy",
        "s3:DeleteBucket",
        "s3:PutBucketAcl",
      ]
      resources = [
        aws_s3_bucket.app.arn,
        "${aws_s3_bucket.app.arn}/*",
      ]
    }
  }
}

resource "aws_iam_policy" "app_s3" {
  name        = "${local.name_prefix}-app-s3"
  description = "Least-privilege S3 access for ${local.name_prefix} application"
  policy      = data.aws_iam_policy_document.app_s3.json

  tags = local.common_tags
}

# --- Trust policy: OIDC (prod / IRSA) or IAM user (dev) --------------------

data "aws_iam_policy_document" "assume_role_oidc" {
  count = var.oidc_provider_arn != "" ? 1 : 0

  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = [var.oidc_provider_arn]
    }

    condition {
      test     = "StringEquals"
      variable = "${var.oidc_provider_url}:sub"
      values   = ["system:serviceaccount:${var.service_account_namespace}:${var.service_account_name}"]
    }

    condition {
      test     = "StringEquals"
      variable = "${var.oidc_provider_url}:aud"
      values   = ["sts.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "app" {
  name = "${local.name_prefix}-app-role"

  assume_role_policy = var.oidc_provider_arn != "" ? data.aws_iam_policy_document.assume_role_oidc[0].json : jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        AWS = aws_iam_user.app[0].arn
      }
    }]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "app_s3" {
  role       = aws_iam_role.app.name
  policy_arn = aws_iam_policy.app_s3.arn
}

# --- IAM user for dev (programmatic access when no OIDC) -------------------

resource "aws_iam_user" "app" {
  count = var.oidc_provider_arn == "" ? 1 : 0
  name  = "${local.name_prefix}-app"

  tags = local.common_tags
}

resource "aws_iam_user_policy_attachment" "app_s3" {
  count      = var.oidc_provider_arn == "" ? 1 : 0
  user       = aws_iam_user.app[0].name
  policy_arn = aws_iam_policy.app_s3.arn
}

resource "aws_iam_access_key" "app" {
  count = var.oidc_provider_arn == "" ? 1 : 0
  user  = aws_iam_user.app[0].name
}
```

### `outputs.tf`

```terraform
# --- S3 --------------------------------------------------------------------

output "bucket_id" {
  description = "S3 bucket name"
  value       = aws_s3_bucket.app.id
}

output "bucket_arn" {
  description = "S3 bucket ARN"
  value       = aws_s3_bucket.app.arn
}

output "bucket_regional_domain_name" {
  description = "S3 bucket regional domain name"
  value       = aws_s3_bucket.app.bucket_regional_domain_name
}

output "replica_bucket_arn" {
  description = "Replica bucket ARN (empty if replication disabled)"
  value       = var.enable_replication ? aws_s3_bucket.replica[0].arn : ""
}

# --- RDS -------------------------------------------------------------------

output "db_endpoint" {
  description = "RDS connection endpoint"
  value       = aws_db_instance.app.endpoint
}

output "db_address" {
  description = "RDS hostname"
  value       = aws_db_instance.app.address
}

output "db_port" {
  description = "RDS port"
  value       = aws_db_instance.app.port
}

output "db_name" {
  description = "Database name"
  value       = aws_db_instance.app.db_name
}

output "db_arn" {
  description = "RDS instance ARN"
  value       = aws_db_instance.app.arn
}

# --- IAM -------------------------------------------------------------------

output "app_role_arn" {
  description = "IAM role ARN for the application service account"
  value       = aws_iam_role.app.arn
}

output "app_user_arn" {
  description = "IAM user ARN (empty when using OIDC)"
  value       = var.oidc_provider_arn == "" ? aws_iam_user.app[0].arn : ""
}

output "app_access_key_id" {
  description = "Access key ID (empty when using OIDC)"
  value       = var.oidc_provider_arn == "" ? aws_iam_access_key.app[0].id : ""
  sensitive   = true
}

output "app_secret_access_key" {
  description = "Secret access key (empty when using OIDC)"
  value       = var.oidc_provider_arn == "" ? aws_iam_access_key.app[0].secret : ""
  sensitive   = true
}

# --- Connection string (for secret store) -----------------------------------

output "db_connection_string" {
  description = "PostgreSQL connection string"
  value       = "postgresql://${var.db_username}:${var.db_password}@${aws_db_instance.app.address}:${aws_db_instance.app.port}/${var.db_name}"
  sensitive   = true
}
```

