## Environment: `environments/prod/`

### `backend.tf`

```terraform
terraform {
  backend "s3" {
    bucket         = "myproject-terraform-state"
    key            = "app-infrastructure/prod/terraform.tfstate"
    region         = "us-east-1"
    encrypt        = true
    dynamodb_table = "terraform-locks"
  }
}
```

### `main.tf`

```terraform
provider "aws" {
  region = var.region
}

provider "aws" {
  alias  = "replica"
  region = "us-west-2"
}

module "app_infrastructure" {
  source = "../../modules/app-infrastructure"

  providers = {
    aws         = aws
    aws.replica = aws.replica
  }

  project     = var.project
  environment = "prod"
  region      = var.region

  # S3 — with cross-region replication
  bucket_name        = var.bucket_name
  enable_replication = true
  replication_region = "us-west-2"

  # RDS — multi-AZ, larger instance
  db_instance_class          = var.db_instance_class
  db_name                    = var.db_name
  db_username                = var.db_username
  db_password                = var.db_password
  db_multi_az                = true
  db_allocated_storage       = 100
  db_backup_retention_period = 30
  db_subnet_ids              = var.db_subnet_ids
  db_security_group_ids      = var.db_security_group_ids

  # IAM — prod uses OIDC / IRSA (no static keys)
  oidc_provider_arn       = var.oidc_provider_arn
  oidc_provider_url       = var.oidc_provider_url
  service_account_namespace = "app"
  service_account_name      = "app-sa"

  tags = var.tags
}

variable "project"               { type = string }
variable "region"                { type = string }
variable "bucket_name"           { type = string }
variable "db_instance_class"     { type = string }
variable "db_name"               { type = string }
variable "db_username"           { type = string; sensitive = true }
variable "db_password"           { type = string; sensitive = true }
variable "db_subnet_ids"         { type = list(string) }
variable "db_security_group_ids" { type = list(string) }
variable "oidc_provider_arn"     { type = string }
variable "oidc_provider_url"     { type = string }
variable "tags"                  { type = map(string); default = {} }

output "bucket_id"              { value = module.app_infrastructure.bucket_id }
output "replica_bucket_arn"     { value = module.app_infrastructure.replica_bucket_arn }
output "db_endpoint"            { value = module.app_infrastructure.db_endpoint }
output "app_role_arn"           { value = module.app_infrastructure.app_role_arn }
output "db_connection_string"   { value = module.app_infrastructure.db_connection_string; sensitive = true }
```

